const id = $json.params.id;

const isUuid =
    typeof id === 'string' &&
    /^[0-9a-fA-F]{8}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{12}$/.test(id);

return { id, valido: isUuid }

const body = $input.first().json.body ?? {};

const { cliente_id, titulo, descricao } = body;

const erros = [];

const isUuid = (value) =>
    typeof value === 'string' &&
    /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/.test(value);

if (!cliente_id) {
    erros.push('cliente_id é obrigatório');
} else if (!isUuid(cliente_id)) {
    erros.push('cliente_id inválido');
}

if (!titulo) {
    erros.push('título é obrigatório');
} else if (typeof titulo !== 'string' || titulo.trim().length < 2) {
    erros.push('título inválido');
}

if (!descricao) {
    erros.push('descrição é obrigatória');
} else if (typeof descricao !== 'string' || descricao.trim().length < 8) {
    erros.push('descrição deve ter pelo menos 8 caracteres');
}

return [{
    json: {
        cliente_id,
        titulo: titulo,
        descricao: descricao,
        erros,
        valido: erros.length === 0
    }
}];

const id = $json.params.id;

const isUuid =
    typeof id === 'string' &&
    /^[0-9a-fA-F]{8}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{12}$/.test(id);

return { id, valido: isUuid }

const query = $json.query ?? {};

const STATUS_VALIDOS = ['aberto', 'em_atendimento', 'aguardando_cliente', 'resolvido', 'cancelado'];
const PRIORIDADES_VALIDAS = ['baixa', 'media', 'alta'];

const status = query.status?.trim() || null;
const prioridade = query.prioridade?.trim() || null;

const erros = [];
if (status && !STATUS_VALIDOS.includes(status)) erros.push('status inválido');
if (prioridade && !PRIORIDADES_VALIDAS.includes(prioridade)) erros.push('prioridade inválida');

if (erros.length > 0) {
  return [{ json: { valido: false, erros } }];
}

let sql = 'select * from tickets where 1=1';
const params = [];

if (status) {
  params.push(status);
  sql += ` and status = $${params.length}`;
}
if (prioridade) {
  params.push(prioridade);
  sql += ` and prioridade = $${params.length}`;
}
sql += ' order by criado_em desc';

return [{ json: { valido: true, sql, params } }];

const id = $json.params.id;

const isUuid =
    typeof id === 'string' &&
    /^[0-9a-fA-F]{8}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{12}$/.test(id);

return { id, valido: isUuid }

const mensagem = $("registrar interação").first().json.body.mensagem ?? null;

const erros = [];

if (!mensagem) {
    erros.push('mensagem é obrigatória');
} else if (typeof mensagem !== 'string' || mensagem.trim().length < 5) {
    erros.push('mensagem inválida');
}

return [{
    json: {
        mensagem,
        erros,
        valido: erros.length === 0
    }
}];

const id = $json.params.id;
const { status } = $json.body ?? {};
const erros = [];

const STATUS_VALIDOS = ['aberto', 'em_atendimento', 'aguardando_cliente', 'resolvido', 'cancelado'];

const isUuid =
    typeof id === 'string' &&
    /^[0-9a-fA-F]{8}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{12}$/.test(id);

if (!isUuid) erros.push("ID inválido")

if (!status) erros.push('status é obrigatório');
else if (!STATUS_VALIDOS.includes(status)) erros.push('status inválido');

return [{ json: { id, status, erros, valido: erros.length === 0 } }];
